sed -i '/removeOutputGroup: (id: string) => void;/a\  setLivePanelCount: (count: number) => void;' src/store/useStore.ts

sed -i '/removeOutputGroup: (id) => {/i\  setLivePanelCount: async (count) => {\n    const state = get();\n    let current = [...state.outputGroups];\n    if (current.length === count) return;\n    if (current.length > count) {\n      const toRemove = current.slice(count);\n      current = current.slice(0, count);\n      await Promise.all(toRemove.map(g => dbApi.deleteOutputGroup(g.id)));\n    } else {\n      const toAdd = [];\n      for (let i = current.length; i < count; i++) {\n        toAdd.push({\n          id: `group-dynamic-${Date.now()}-${i}`,\n          name: `Display ${i + 1}`,\n          role: "confidence" as const,\n          displayIds: [],\n          isBlack: false,\n          isClear: false,\n          showLogo: true\n        });\n      }\n      current = [...current, ...toAdd];\n      await Promise.all(toAdd.map(g => dbApi.saveOutputGroup(g)));\n    }\n    set({ outputGroups: current });\n  },' src/store/useStore.ts
